<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import * as api from '@/api/admin-practice'
import {createSubjective,saveSubjective,type SubjectiveContent,type SubjectiveInput} from '@/api/practice-subjective'
import {blankMetadata} from '@/practice/admin-draft'
import {errorMessage} from '@/api/identity'
import {ApiError} from '@/api/client'
import {getGeneration,onRemoteIdentityChange} from '@/auth/token-session'
import {useAuthStore} from '@/stores/auth'
import '@/styles/practice.css'
import '@/styles/practice-subjective.css'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),record=ref<api.AdminSet>(),metadata=ref(blankMetadata()),type=ref('WRITING'),content=ref<SubjectiveContent>({prompt:'',requirements:'',minWords:120,maxWords:180,minutes:30,reference:'',notes:''}),busy=ref(false),loading=ref(false),error=ref(''),notice=ref(''),baseline=ref(''),conflict=ref(false),versions=ref<api.PublishedVersion[]>([]),versionPage=ref(1),versionTotal=ref(0),preview=ref<api.PublishedVersion>(),previewDialog=ref<HTMLDialogElement>();let epoch=0,disposed=false,relocating=false
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const snapshot=()=>JSON.stringify({metadata:metadata.value,readingType:type.value,subjective:content.value}),dirty=computed(()=>snapshot()!==baseline.value),label=computed(()=>type.value==='WRITING'?'写作':'翻译'),checks=computed(()=>record.value?.checks||[])
function apply(r:api.AdminSet){record.value=r;metadata.value=clone(r.metadata);type.value=r.readingType;content.value=clone(r.subjective!);baseline.value=snapshot();conflict.value=false}
const scope=()=>{const e=epoch,g=getGeneration(),owner=auth.user?.id;return()=>!disposed&&e===epoch&&g===getGeneration()&&owner===auth.user?.id}
async function load(){epoch++;const valid=scope();loading.value=true;error.value='';notice.value='';record.value=undefined;versions.value=[];preview.value=undefined;metadata.value=blankMetadata();type.value='WRITING';content.value={prompt:'',requirements:'',minWords:120,maxWords:180,minutes:30,reference:'',notes:''};baseline.value=snapshot();try{if(route.params.id!=='new'){const r=await api.adminPracticeSet(String(route.params.id));if(valid()){if(!r.subjective){await router.replace('/admin/practice/'+r.id);return}apply(r)}}}catch(e){if(valid())error.value=errorMessage(e)}finally{if(valid())loading.value=false}}
function changeType(){if(type.value==='TRANSLATION'){content.value.minWords=null;content.value.maxWords=null;content.value.minutes=15}else{content.value.minWords=120;content.value.maxWords=180;content.value.minutes=30}}
async function save(){if(busy.value||loading.value||conflict.value)return false;const valid=scope();busy.value=true;error.value='';notice.value='';const input:SubjectiveInput={readingType:type.value,metadata:clone(metadata.value),subjective:clone(content.value),expectedLockVersion:record.value?.lockVersion||0};try{const r=record.value?await saveSubjective(record.value.id,input):await createSubjective(input);if(!valid())return false;apply(r);notice.value='草稿已保存，公开版本保持原样。';if(route.params.id==='new'){relocating=true;await router.replace('/admin/practice/subjective/'+r.id);relocating=false}return true}catch(e){if(valid()){error.value=errorMessage(e)+(e instanceof ApiError&&e.fieldErrors?' · '+Object.values(e.fieldErrors).join('；'):'');if(e instanceof ApiError&&e.status===409)conflict.value=true}return false}finally{if(valid())busy.value=false}}
async function action(kind:'CONTENT'|'SOURCE'|'publish'|'unpublish'){if(!record.value||busy.value||dirty.value||conflict.value)return;try{if(kind==='CONTENT'||kind==='SOURCE')await ElMessageBox.confirm(kind==='CONTENT'?'确认已人工核对题目、参考文本及对照要点？':'确认已核实来源信息和当前使用范围？','确认校对',{confirmButtonText:'已核对，确认',cancelButtonText:'返回检查',autofocus:false});else await ElMessageBox.confirm(kind==='publish'?'发布当前已校对版本，供学员开始练习？':'下架后不再允许新开始；已有练习仍保留。','确认操作',{confirmButtonText:kind==='publish'?'发布版本':'确认下架',cancelButtonText:'取消',autofocus:false})}catch{return}const valid=scope();busy.value=true;error.value='';try{const r=kind==='publish'||kind==='unpublish'?await api.practiceSetStatus(record.value.id,record.value.lockVersion,kind==='publish'):await api.reviewPracticeSet(record.value.id,record.value.lockVersion,kind,true);if(valid()){apply(r);notice.value=kind==='publish'?'版本已发布':kind==='unpublish'?'已下架':'校对状态已保存'}}catch(e){if(valid()){error.value=errorMessage(e)+(e instanceof ApiError&&e.fieldErrors?' · '+Object.values(e.fieldErrors).join('；'):'');if(e instanceof ApiError&&e.status===409)conflict.value=true}}finally{if(valid())busy.value=false}}
async function loadVersions(page=1){if(!record.value)return;const valid=scope();busy.value=true;try{const p=await api.adminPracticeVersions(record.value.id,page);if(valid()){versions.value=p.items;versionPage.value=page;versionTotal.value=p.total}}catch(e){if(valid())error.value=errorMessage(e)}finally{if(valid())busy.value=false}}
function showPreview(v?:api.PublishedVersion){preview.value=v||{revision:record.value?.revision||0,publishedAt:'',metadata:clone(metadata.value),article:record.value?.article as api.PublishedVersion['article'],questions:[],readingType:type.value,subjective:clone(content.value)};previewDialog.value?.showModal()}
function locate(path:string){document.getElementById(path)?.focus();document.getElementById(path)?.scrollIntoView({block:'center',behavior:'smooth'})}
async function leave(){if(relocating)return true;if(busy.value)return false;if(!dirty.value)return true;try{await ElMessageBox.confirm('有未保存的题目内容，离开将放弃本地修改。','尚未保存',{confirmButtonText:'放弃本地修改并离开',cancelButtonText:'留在这里',autofocus:false});return true}catch{return false}}
function unload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
function clearPrivate(){epoch++;record.value=undefined;metadata.value=blankMetadata();content.value={prompt:'',requirements:'',minWords:null,maxWords:null,minutes:null,reference:'',notes:''};versions.value=[];preview.value=undefined;previewDialog.value?.close();baseline.value=snapshot();busy.value=false;error.value='账号已变化，请重新加载';}
const off=onRemoteIdentityChange(clearPrivate);watch(()=>auth.user?.id,clearPrivate,{flush:'sync'});watch(()=>route.params.id,()=>{if(relocating)return;void load()},{immediate:true});onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave);window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>{disposed=true;off();window.removeEventListener('beforeunload',unload)})
</script>
<template><section class="practice-page practice-subjective subjective-admin"><RouterLink to="/admin/practice">← 返回专项题组</RouterLink><header class="practice-heading"><div><h1>{{record?'编辑':'新建'}}{{label}}题目</h1><p class="practice-hint">独立专项材料，参考内容仅提交后解锁。保存草稿后分别确认内容与来源校对。</p></div><span v-if="record" class="practice-tag">{{{DRAFT:'草稿',PUBLISHED:'已发布',UNLISTED:'已下架'}[record.status]}} · v{{record.revision}}</span></header><p v-if="loading" role="status">正在加载…</p><p v-if="error" role="alert" class="practice-notice practice-error">{{error}}</p><p v-if="notice" role="status" class="practice-notice">{{notice}}</p><div v-if="conflict" class="practice-notice">请先复制本地修改，重新加载会读取服务器版本。<button @click="load">重新加载</button></div><form v-if="!loading" @submit.prevent="save"><fieldset :disabled="busy||conflict"><legend>题目信息</legend><div class="subjective-fields"><label>题目类型<select aria-label="题目类型" v-model="type" :disabled="!!record" @change="changeType"><option value="WRITING">写作</option><option value="TRANSLATION">翻译</option></select></label><label>来源<select v-model="metadata.sourceKind"><option value="ORIGINAL">原创练习（含外部AI辅助）</option><option value="PAST">真实来源试题</option></select></label><label>英文标题<input id="metadata.title" v-model="metadata.title" maxlength="200"></label><label>中文标题<input id="metadata.titleZh" v-model="metadata.titleZh" maxlength="500"></label><label>主题<select v-model="metadata.topic"><option value="education">教育</option><option value="culture">文化</option><option value="life">生活</option><option value="technology">科技</option></select></label><label>建议时间（分钟）<input v-model.number="content.minutes" type="number" min="1" max="180"></label><template v-if="type==='WRITING'"><label>建议最少词数<input v-model.number="content.minWords" type="number" min="1" max="5000"></label><label>建议最多词数<input v-model.number="content.maxWords" type="number" min="1" max="5000"></label></template><template v-if="metadata.sourceKind==='PAST'"><label>真实考试年份<input id="metadata.year" v-model.number="metadata.year" type="number" min="2000" max="2100"></label><label>考试月份<select id="metadata.month" v-model.number="metadata.month"><option :value="null">请选择</option><option v-for="month in [6,12,9,7,3]" :key="month" :value="month">{{month}}月</option></select></label><label>套次<input id="metadata.paperNo" v-model.number="metadata.paperNo" type="number" min="1" max="9"></label></template><label>来源名称<input id="metadata.sourceName" v-model="metadata.sourceName" maxlength="500"></label><label>来源网址<input v-model="metadata.sourceUrl" maxlength="2000"></label><label>使用说明<textarea id="metadata.usageNote" v-model="metadata.usageNote" maxlength="2000" placeholder="说明原创/AI辅助，或真实来源与允许的使用范围"/></label></div></fieldset><fieldset :disabled="busy||conflict"><legend>题目与参考内容</legend><label>{{type==='WRITING'?'题目要求 / Directions':'中文翻译材料'}}<textarea id="subjective.prompt" v-model="content.prompt" class="subjective-prompt-edit" maxlength="20000"/></label><label>详细要求与提示<textarea v-model="content.requirements" maxlength="4000"/></label><label>{{type==='WRITING'?'参考范文':'参考译文'}}（学员提交前不可见）<textarea id="subjective.reference" v-model="content.reference" maxlength="20000"/></label><label>对照要点（学员提交前不可见）<textarea id="subjective.notes" v-model="content.notes" maxlength="10000"/></label></fieldset><div class="practice-actions"><button class="button-primary" :disabled="busy||conflict">{{busy?'处理中…':'保存草稿'}}</button><button type="button" @click="showPreview()">预览题目与参考</button><span role="status" class="practice-hint">{{dirty?'有未保存修改':'当前内容已保存'}}</span></div></form><section v-if="record" class="practice-panel subjective-checks"><h2>发布检查</h2><p v-if="dirty" class="practice-hint">内容已修改，请先保存再校对。以下为上次保存状态。</p><ul v-if="checks.length"><li v-for="c in checks" :key="c.path"><a :href="'#'+c.path" @click.prevent="locate(c.path)">{{c.message}}</a></li></ul><p v-else>内容与来源检查已完成。</p><div class="practice-actions"><button id="contentReview" :disabled="busy||dirty||conflict" @click="action('CONTENT')">确认内容校对</button><button id="sourceReview" :disabled="busy||dirty||conflict" @click="action('SOURCE')">确认来源校对</button><button class="button-primary" :disabled="busy||dirty||conflict||!!checks.length" @click="action('publish')">发布新版本</button><button v-if="record.status==='PUBLISHED'" :disabled="busy||dirty||conflict" @click="action('unpublish')">下架</button></div></section><section v-if="record?.revision" class="practice-panel"><h2>已发布版本</h2><button :disabled="busy" @click="loadVersions()">加载版本记录</button><ul><li v-for="v in versions" :key="v.revision"><button @click="showPreview(v)">v{{v.revision}} · {{new Date(v.publishedAt).toLocaleString()}}</button></li></ul><div v-if="versions.length" class="practice-actions"><button :disabled="busy||versionPage<=1" @click="loadVersions(versionPage-1)">上一页</button><button :disabled="busy||versionPage*20>=versionTotal" @click="loadVersions(versionPage+1)">下一页</button></div></section><dialog ref="previewDialog"><template v-if="preview"><header class="practice-actions"><h2>{{preview.metadata.titleZh||preview.metadata.title}}</h2><button @click="previewDialog?.close()">关闭预览</button></header><p class="subjective-material">{{preview.subjective?.prompt}}</p><p class="subjective-material">{{preview.subjective?.requirements}}</p><h3>参考内容（仅管理员预览）</h3><p class="subjective-material">{{preview.subjective?.reference}}</p><h3>对照要点</h3><p class="subjective-material">{{preview.subjective?.notes}}</p></template></dialog></section></template>
